CREATE OR REPLACE FUNCTION public.supply_conversation_users(_order_id uuid) RETURNS TABLE(id uuid, full_name text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,p.full_name FROM public.profiles p WHERE auth.uid() IS NOT NULL AND p.is_active AND p.deleted_at IS NULL AND EXISTS(SELECT 1 FROM public.purchase_orders o WHERE o.id=_order_id AND (o.requester_id=auth.uid() OR public.can_edit_supply_purchase())) AND (p.id=(SELECT requester_id FROM public.purchase_orders WHERE id=_order_id) OR (EXISTS(SELECT 1 FROM public.user_app_access a WHERE a.user_id=p.id AND a.app_key='supply') AND (public.has_role(p.id,'admin') OR public.is_supply_member(p.id)))) ORDER BY p.full_name; $$;
REVOKE ALL ON FUNCTION public.supply_conversation_users(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.supply_conversation_users(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.guard_supply_order_message() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.purchase_orders%ROWTYPE; parent public.supply_order_messages%ROWTYPE; buyer boolean; BEGIN IF auth.uid() IS NULL OR NEW.author_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Autor inválido.' USING ERRCODE='42501'; END IF; SELECT * INTO o FROM public.purchase_orders WHERE id=NEW.order_id FOR UPDATE; IF NOT FOUND OR o.status='cancelado' OR o.request_type='pagamento' THEN RAISE EXCEPTION 'Pedido indisponível para conversa.'; END IF; buyer:=public.can_edit_supply_purchase(); IF o.requester_id<>auth.uid() AND NOT buyer THEN RAISE EXCEPTION 'Somente Solicitante e Compras podem conversar.' USING ERRCODE='42501'; END IF; IF NEW.message_type='question' THEN IF NEW.recipient_id IS NOT NULL THEN IF NEW.recipient_id=auth.uid() OR NOT EXISTS(SELECT 1 FROM public.supply_conversation_users(NEW.order_id) u WHERE u.id=NEW.recipient_id) THEN RAISE EXCEPTION 'Destinatário inválido.' USING ERRCODE='42501'; END IF; ELSIF auth.uid()<>o.requester_id THEN NEW.recipient_id:=o.requester_id; END IF; ELSE SELECT * INTO parent FROM public.supply_order_messages WHERE id=NEW.parent_message_id; IF parent.order_id IS DISTINCT FROM NEW.order_id OR parent.message_type IS DISTINCT FROM 'question' OR parent.author_id=auth.uid() THEN RAISE EXCEPTION 'Pergunta inválida.'; END IF; IF (parent.recipient_id IS NOT NULL AND parent.recipient_id<>auth.uid()) OR (parent.recipient_id IS NULL AND (NOT buyer OR auth.uid()=o.requester_id)) THEN RAISE EXCEPTION 'Sem permissão para responder.' USING ERRCODE='42501'; END IF; IF EXISTS(SELECT 1 FROM public.supply_order_messages WHERE parent_message_id=parent.id) THEN RAISE EXCEPTION 'Pergunta já respondida.'; END IF; NEW.recipient_id:=NULL; END IF; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.guard_supply_order_message() FROM PUBLIC,anon,authenticated;